  R("ambient_a", "Open-shroud proposal", "Ren proposed calibrating with the shroud open to simplify tile placement. The proposal is disputed because room lighting can contaminate the reading.", kind="hypothesis", status="disputed", epistemic="claimed", revision="proposal-a"),
  R("ambient_b", "Closed-shroud proposal", "Miko proposed calibrating with the shroud closed around the tile. This competing proposal is disputed pending a repeatability study of the placement mechanism.", kind="hypothesis", status="disputed", epistemic="claimed", revision="proposal-b"),
  R("decision", "Current shroud procedure", "The current supported Violet procedure closes the shroud before white-reference capture. The open-shroud proposal has not replaced this procedure.", kind="decision"),
